def install(catalog):
    """Append new templates, identity lists and all-quality gear permissions."""
    catalog.rules['mercenaries'].update(deepcopy(MERCENARIES))
    catalog.rules['hero_templates'].update(deepcopy(HEROES))
    catalog.rules['profession_ids']=sorted(set(catalog.rules.get('profession_ids',[]))|set(catalog.rules['mercenaries']))
    catalog.rules['hero_ids']=sorted(set(catalog.rules.get('hero_ids',[]))|set(catalog.rules['hero_templates'])|{'H07'})
    for item in catalog.gear.values():
        family=item.get('family_id',item['template_id'].split('-')[0])
        allowed=item['allowed_unit_ids']
        for identity,families in GEAR_FAMILIES.items():
            if family in families and identity not in allowed:allowed.append(identity)
